import numpy as np

def check_axioms(p, tol=1e-9):
    axiom1 = bool(np.all(p >= 0))
    axiom2 = bool(abs(p.sum() - 1.0) < tol)
    return {"non_negative": axiom1, "sums_to_one": axiom2}

valid = np.array([0.1, 0.2, 0.3, 0.4])
invalid_negative = np.array([0.5, -0.1, 0.3, 0.3])
invalid_sum = np.array([0.1, 0.2, 0.3, 0.3])   # sums to 0.9, not 1

for name, p in [("valid", valid), ("negative", invalid_negative), ("bad_sum", invalid_sum)]:
    print(name, check_axioms(p))

import math

def prob_no_shared_birthday(n, days=365):
    return math.perm(days, n) / (days ** n)

for n in [10, 20, 23, 30, 50]:
    p_no_collision = prob_no_shared_birthday(n)
    print(n, round(1 - p_no_collision, 4))   # probability of AT LEAST one shared birthday

# Same math, reframed: probability of at least one collision among n random
# 16-bit IDs (65536 possible values) -- collisions become likely far sooner
# than intuition suggests, exactly like the birthday problem
for n in [50, 100, 200, 300]:
    p_no_collision = prob_no_shared_birthday(n, days=65536)
    print(n, round(1 - p_no_collision, 4))

from scipy.stats import norm

weights = [0.7, 0.3]
means = [-1.0, 3.0]
stds = [0.8, 1.2]

def marginal_density(x):
    return sum(w * norm.pdf(x, loc=m, scale=s) for w, m, s in zip(weights, means, stds))

for x in [-1.0, 0.0, 1.0, 3.0]:
    print(x, round(marginal_density(x), 5))

def bayes_posterior(prior, sensitivity, false_positive_rate):
    evidence = sensitivity * prior + false_positive_rate * (1 - prior)
    return sensitivity * prior / evidence

for prior in [0.5, 0.01, 0.001, 0.0001]:
    posterior = bayes_posterior(prior, sensitivity=0.99, false_positive_rate=0.01)
    print(f"prevalence={prior:<8} -> P(condition | positive)={posterior:.4f}")

hypotheses = {"variant_A_better": 0.5, "variant_B_better": 0.5}
p_conversion = {"variant_A_better": 0.6, "variant_B_better": 0.4}   # likelihoods

observations = ["convert", "no_convert", "convert", "convert", "convert"]

for obs in observations:
    unnormalized = {}
    for h, prior in hypotheses.items():
        likelihood = p_conversion[h] if obs == "convert" else (1 - p_conversion[h])
        unnormalized[h] = likelihood * prior
    evidence = sum(unnormalized.values())
    hypotheses = {h: v / evidence for h, v in unnormalized.items()}

print(hypotheses)   # belief has shifted toward variant_A_better after this evidence stream

import numpy as np

# P(word appears | class) estimated from a tiny toy training set
p_word_given_spam = {"free": 0.6, "winner": 0.5, "meeting": 0.05}
p_word_given_not_spam = {"free": 0.05, "winner": 0.02, "meeting": 0.4}
prior_spam, prior_not_spam = 0.4, 0.6

def naive_bayes_score(words_present, p_word_given_class, prior):
    score = prior
    for word, p_word in p_word_given_class.items():
        score *= p_word if word in words_present else (1 - p_word)
    return score

email_words = {"free", "winner"}
score_spam = naive_bayes_score(email_words, p_word_given_spam, prior_spam)
score_not_spam = naive_bayes_score(email_words, p_word_given_not_spam, prior_not_spam)

print("spam score:", score_spam, "not-spam score:", score_not_spam)
print("predicted:", "spam" if score_spam > score_not_spam else "not spam")
